def solve(nums, target):
    """
    Finds the first and last indices of target in sorted list nums.
    """
    first = -1
    last = -1

    if not nums:
        return [first, last]

    low = 0
    high = len(nums) - 1

    # Find the first occurrence
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            first = mid
            high = mid - 1  # Continue searching in the left half
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    low = 0
    high = len(nums) - 1

    # Find the last occurrence
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            last = mid
            low = mid + 1  # Continue searching in the right half
        elif nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return [first, last]

